/** Build one self-contained installer; generated files never contain private data. */
import * as fs from 'node:fs';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
import {createHash} from 'node:crypto';
const directory=path.dirname(fileURLToPath(import.meta.url));
const read=name=>fs.readFileSync(path.join(directory,name),'utf8');
const channel='https://raw.githubusercontent.com/JBrickey23/Cookie_Catalog/feature/cc-infrastructure-foundation/tools';
export function buildBundle(){
  const crlf=s=>s.replace(/\r?\n/g,'\r\n');
  const launcher=mode=>crlf(`@echo off\nsetlocal DisableDelayedExpansion\nnode "%~dp0Tools\\Backup\\run.mjs" ${mode} "%~1"\nset "kit_exit=%errorlevel%"\necho.\npause\nexit /b %kit_exit%\n`);
  const refresh=`$ErrorActionPreference='Stop'; try { $base='${channel}'; $r=Invoke-RestMethod -Uri ($base+'/backup-kit-release.json'); if($r.format -ne 'cookie-catalog-backup-kit-release' -or $r.version -ne 1 -or $r.sha256 -notmatch '^[a-f0-9]{64}$'){throw 'Invalid tool release.'}; $f=Join-Path $env:TEMP ('CookieCatalogSetup_'+[guid]::NewGuid().ToString('N')+'.mjs'); Invoke-WebRequest -UseBasicParsing -Uri ($base+'/backup-kit-installer.mjs') -OutFile $f; if((Get-FileHash -LiteralPath $f -Algorithm SHA256).Hash -ne $r.sha256){throw 'Tool download checksum failed. Existing tools were kept.'}; $root=$env:COOKIE_CATALOG_KIT_ROOT.TrimEnd([char]92); & node $f --root $root; exit $LASTEXITCODE } catch { [Console]::Error.WriteLine($_.Exception.Message); exit 1 }`;
  return {format:'cookie-catalog-backup-kit',version:1,assets:{
    'backup-helper.mjs':read('backup-helper.mjs'),
    'backup-kit.mjs':read('backup-kit.mjs').replace("'../app/src/archive-format.ts'","'./archive-format.mts'"),
    'archive-format.mts':read('../app/src/archive-format.ts')
  },managed:{
    'Backup.cmd':launcher('normal'),
    'Pre-Change-Backup.cmd':launcher('pre-change'),
    'Review-Backups.cmd':launcher('review'),
    'Verify-Cloud-Copy.cmd':launcher('verify-cloud'),
    'Open-Backup-Inbox.cmd':crlf('@echo off\nsetlocal DisableDelayedExpansion\nnode "%~dp0Tools\\Backup\\run.mjs" open-inbox\nif errorlevel 1 pause\n'),
    'Open-Saved-Backups.cmd':crlf('@echo off\nsetlocal DisableDelayedExpansion\nnode "%~dp0Tools\\Backup\\run.mjs" open-backups\nif errorlevel 1 pause\n'),
    'Refresh-Backup-Tools.cmd':crlf(`@echo off\nsetlocal DisableDelayedExpansion\nset "COOKIE_CATALOG_KIT_ROOT=%~dp0"\npowershell.exe -NoProfile -Command "${refresh}"\nset "kit_exit=%errorlevel%"\necho.\npause\nexit /b %kit_exit%\n`),
    'Tools/Backup/run.mjs':read('backup-kit-runtime.mjs'),
    'Tools/Backup/README.txt':`Cookie Catalog backup tools\n\nSave a fresh complete app backup into Backups\\Inbox. No special filename is required.\nDouble-click Backup.cmd, or Pre-Change-Backup.cmd before changing catalog data.\nThe helper validates the input and saves a verified copy plus receipt in the existing Backups folder.\nIf Inbox is empty, it checks ordinary Downloads and unreceipted backups already in Backups.\nTAR files, complete extracted app TAR folders and small development-backup JSON files are supported.\nTool ZIPs and OneNote/PDF source exports are not catalog backups.\nRepeated identical archives reuse a verified saved copy of the same backup kind.\nNothing moves or deletes source files or existing backups.\n\nRefresh-Backup-Tools.cmd updates only managed tools. Settings, input and backups stay in place.\nPaths are relative to this Cookie_Catalog folder, so moving the whole folder keeps the kit usable.\nSettings: Tools\\Backup\\settings.json. Current tool version: Tools\\Backup\\current.json.\nNo PowerShell execution-policy change, npm, Python, paid resource or login is needed.\nOnly explicit setup/refresh contacts the public GitHub source. Normal saves are offline.\n\nExport time is displayed. This verifies the supplied export, not the current live server.\nBefore a migration/import, first create a fresh export in the app, then run Pre-Change-Backup.cmd.\nDownload a saved backup from OneDrive web, then drag that TAR onto Verify-Cloud-Copy.cmd.\nThe matching local receipt is found automatically. This proves byte identity, not provider provenance.\n`
  }};
}
export function installerSource(bundle=buildBundle()){
  return '// GENERATED by tools/build-backup-kit.mjs. Do not edit this distribution file.\n'+read('backup-kit-install-core.mjs')+'\nconst BUNDLE='+JSON.stringify(bundle)+';\n'+
    `if(process.argv[1]&&import.meta.url===pathToFileURL(path.resolve(process.argv[1])).href){try{const args=process.argv.slice(2),index=args.indexOf('--root');if(args.some((a,i)=>a!=='--json'&&a!=='--root'&&!(index>=0&&i===index+1))||index>=0&&!args[index+1])throw Error('Use --root EXISTING_FOLDER and/or --json.');const result=installKit(BUNDLE,index<0?undefined:args[index+1]);console.log(args.includes('--json')?JSON.stringify(result):'Backup tools ready: '+result.root+'\\nUse Backup.cmd or Pre-Change-Backup.cmd. Your backups and settings were preserved.');}catch(error){console.error('Backup tool setup: '+error.message);process.exitCode=1;}}\n`;
}
export function generatedFiles(){
  const source=installerSource(),sha256=createHash('sha256').update(source).digest('hex');
  return {'backup-kit-installer.mjs':source,'backup-kit-release.json':JSON.stringify({format:'cookie-catalog-backup-kit-release',version:1,sha256,bytes:Buffer.byteLength(source)},null,2)+'\n'};
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  for(const [name,content] of Object.entries(generatedFiles())){
    const file=path.join(directory,name);
    if(process.argv.includes('--check')){if(!fs.existsSync(file)||fs.readFileSync(file,'utf8')!==content)throw Error('Rebuild stale installer: '+name);}
    else fs.writeFileSync(file,content);
  }
  console.log(process.argv.includes('--check')?'Backup installer matches its source.':'Backup installer and release checksum generated.');
}
